scripts.storybook:
bun -e 'import createApp from "@storybook/app"
const context = {signal: AbortSignal.timeout(120000)}
const result = await createApp().ensure({schemaVersion: 1, roots: [process.cwd()]}, context)
console.log(JSON.stringify(result, null, 2))
if (result.status !== "success") process.exitCode = 1'

scripts.build:
bun -e 'import createApp from "@storybook/app"
const context = {signal: AbortSignal.timeout(120000)}
const result = await createApp().check({schemaVersion: 1, scope: process.cwd(), live: false}, context)
console.log(JSON.stringify(result, null, 2))
if (result.status !== "success") process.exitCode = 1'

